CREATE TABLE IF NOT EXISTS ranked_flow (match_id TEXT PRIMARY KEY, host_cap INTEGER NOT NULL DEFAULT 0, guest_cap INTEGER NOT NULL DEFAULT 0, connect_mask INTEGER NOT NULL DEFAULT 0, ready_mask INTEGER NOT NULL DEFAULT 0, started_mask INTEGER NOT NULL DEFAULT 0, connect_at INTEGER NOT NULL DEFAULT 0, paired_at INTEGER NOT NULL DEFAULT 0, host_choice INTEGER NOT NULL DEFAULT 0, guest_choice INTEGER NOT NULL DEFAULT 0, choice_until INTEGER NOT NULL DEFAULT 0, next_match TEXT, closed INTEGER NOT NULL DEFAULT 0);
